<script setup lang="ts">
import { ref, reactive, onMounted, onBeforeUnmount } from 'vue'
import { collectionApi, type SourceArchive, type CaptureRecord } from '@/api/collection'
import CollectionLocationPicker from '@/components/collection/CollectionLocationPicker.vue'
const sources=ref<SourceArchive[]>([]),records=ref<CaptureRecord[]>([]),total=ref(0),offset=ref(0),busy=ref(false),error=ref(''),notice=ref('')
const archive=reactive({name:'',origin:'',authorization:'',is_sample:false})
const form=reactive({source_id:'',kind:'photo',captured_at:'',nature:'user_upload',longitude:null as number|null,latitude:null as number|null,note:'',photo_name:''})
const file=ref<File|null>(null),preview=ref(''),selectedPhoto=ref(''),selected=ref<CaptureRecord|null>(null)
const reviewId=ref(''),reviewNote=ref(''),reviewStatus=ref('pending')
let destroyed=false,photoRequest:AbortController|null=null
function message(e:any){const detail=e?.response?.data?.detail;return e?.response?.status===401?'登录已失效，请重新登录。':Array.isArray(detail)?'字段格式不正确，请核对时间、经纬度和必填项。':detail||'保存或加载失败，请检查后端与采集存储配置。'}
async function action(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){if(!destroyed)error.value=String(message(e))}finally{if(!destroyed)busy.value=false}}
async function load(){const [s,r]=await Promise.all([collectionApi.sources(),collectionApi.records(offset.value)]);if(destroyed)return;sources.value=s.items;records.value=r.items;total.value=r.total}
function pickFile(event:Event){const input=event.target as HTMLInputElement;const picked=input.files?.[0];input.value='';if(!picked)return;if(!['image/jpeg','image/png'].includes(picked.type)||picked.size>8*1024*1024){error.value='请选择8MB以内的JPG/PNG照片';return}if(preview.value)URL.revokeObjectURL(preview.value);file.value=picked;preview.value=URL.createObjectURL(picked);if(!form.photo_name)form.photo_name=picked.name.slice(0,160)}
async function saveSource(){await action(async()=>{const s=await collectionApi.source({...archive});form.source_id=String(s.id);archive.name='';archive.origin='';archive.authorization='';archive.is_sample=false;await load();notice.value='来源档案已保存，状态为待核验。'})}
async function save(){await action(async()=>{if(!form.source_id||!form.captured_at)throw {response:{data:{detail:'请选择来源和采集时间'}}};const data=new FormData();for(const [key,value] of Object.entries(form)){if(value!==null&&!(value===''&&['longitude','latitude'].includes(key)))data.append(key,String(key==='captured_at'?new Date(String(value)).toISOString():value))}if(file.value)data.append('photo',file.value);await collectionApi.save(data);offset.value=0;await load();file.value=null;if(preview.value)URL.revokeObjectURL(preview.value);preview.value='';form.photo_name='';notice.value='采集记录已保存到后端；页面标签仅表示用户声明。'})}
async function review(){await action(async()=>{if(!reviewId.value||!reviewNote.value.trim())throw {response:{data:{detail:'请选择来源并填写核验说明'}}};await collectionApi.review(Number(reviewId.value),reviewStatus.value,reviewNote.value);await load();notice.value='核验声明已记录，不代表平台认证。'})}
async function detail(row:CaptureRecord){photoRequest?.abort();if(selectedPhoto.value)URL.revokeObjectURL(selectedPhoto.value);selectedPhoto.value='';selected.value=row;if(!row.photo_url)return;const request=new AbortController();photoRequest=request;try{const blob=await collectionApi.photo(row.id,request.signal);if(!destroyed&&!request.signal.aborted)selectedPhoto.value=URL.createObjectURL(blob)}catch(e){if(!request.signal.aborted)error.value=String(message(e))}}
function sourceName(id:number){return sources.value.find(s=>s.id===id)?.name||`来源 #${id}`}
async function page(delta:number){await action(async()=>{const previous=offset.value;offset.value+=delta;try{await load()}catch(e){offset.value=previous;throw e}})}
function closeDetail(){selected.value=null;photoRequest?.abort();if(selectedPhoto.value)URL.revokeObjectURL(selectedPhoto.value);selectedPhoto.value=''}
onMounted(()=>action(load))
onBeforeUnmount(()=>{destroyed=true;photoRequest?.abort();for(const url of [preview.value,selectedPhoto.value])if(url)URL.revokeObjectURL(url)})
</script>
<template>
<div class="collection-page">
  <header><p class="eyebrow">数据资料 / 采集档案</p><h2>数据采集与来源管理</h2><p>记录照片、位置及资料来源。内容由用户上传或声明，现场与授权真实性须人工核对；记录仅本人账户可访问。</p></header>
  <p class="collection-error" v-if="error" role="alert">{{error}}</p><p v-if="notice" class="collection-success" role="status">{{notice}}</p>
  <button class="refresh" type="button" :disabled="busy" @click="action(load)">刷新记录</button>
  <div class="collection-columns">
    <section class="c-card"><h3>现场照片采集与位置</h3>
      <form @submit.prevent="save">
        <label>关联来源<select v-model="form.source_id" required><option value="">先建立来源档案</option><option v-for="s in sources" :value="String(s.id)" :key="s.id">{{s.name}} · {{s.is_sample?'示例数据':'用户资料'}}</option></select></label>
        <div class="field-row"><label>采集类型<select v-model="form.kind"><option value="photo">照片采集</option><option value="location">位置记录</option><option value="document">资料记录</option></select></label><label>采集时间<input type="datetime-local" v-model="form.captured_at" required /></label></div>
        <label>数据性质<select v-model="form.nature"><option value="user_upload">用户资料（未核验）</option><option value="field_declared">现场采集（用户声明，未经认证）</option><option value="sample">示例数据</option></select></label>
        <label>JPG / PNG照片（8MB以内）<input type="file" accept="image/jpeg,image/png" @change="pickFile" /></label>
        <img v-if="preview" :src="preview" class="photo" alt="待保存照片预览" />
        <label>照片名称<input v-model="form.photo_name" maxlength="160" /></label>
        <div class="field-row"><label>经度（GCJ-02）<input type="number" step="any" min="-180" max="180" v-model.number="form.longitude" @input="selected=null" /></label><label>纬度（GCJ-02）<input type="number" step="any" min="-90" max="90" v-model.number="form.latitude" @input="selected=null" /></label></div>
        <label>说明 / 备注<textarea v-model="form.note" maxlength="2000" rows="3" /></label>
        <button class="primary" type="submit" :disabled="busy">{{busy?'正在处理…':'保存采集记录'}}</button>
      </form>
      <p class="hint">每条记录可关联一张照片；多张照片可建多条记录并关联同一来源。照片可能含EXIF位置，请确认有权保存；不提供公开图片地址。</p>
    </section>
    <div class="right-column">
      <section class="c-card"><h3>空间位置记录</h3><p v-if="selected" class="hint">当前显示已选记录位置；点击地图可切回新记录选点。</p><CollectionLocationPicker :longitude="selected ? selected.longitude : form.longitude" :latitude="selected ? selected.latitude : form.latitude" @pick="(lon,lat)=>{selected=null;form.longitude=lon;form.latitude=lat}" /></section>
      <section class="c-card"><h3>新建来源档案</h3><form @submit.prevent="saveSource"><label>档案名称<input v-model="archive.name" maxlength="160" required /></label><label>原始来源<textarea v-model="archive.origin" maxlength="2000" required /></label><label>授权说明<textarea v-model="archive.authorization" maxlength="2000" required /></label><label class="checkbox"><input type="checkbox" v-model="archive.is_sample" />此档案为示例数据（关联记录强制标为示例）</label><button type="submit" :disabled="busy">保存来源档案</button></form></section>
    </div>
  </div>
  <section class="c-card"><h3>来源核验声明</h3><form class="review-form" @submit.prevent="review"><label>来源<select v-model="reviewId" required><option value="">请选择</option><option v-for="s in sources" :key="s.id" :value="String(s.id)">{{s.name}} · {{s.status==='verified'?'已核验（用户声明）':'待核验'}}</option></select></label><label>数据状态<select v-model="reviewStatus"><option value="pending">待核验</option><option value="verified">已核验（用户声明）</option></select></label><label>核验依据<input v-model="reviewNote" required maxlength="2000" /></label><button :disabled="busy">记录核验声明</button></form><p class="hint">已核验只记录档案所有者的人工声明，不表示平台完成授权审查或独立认证。</p>
  <details v-for="s in sources" :key="s.id"><summary>{{s.name}} · {{s.status==='verified'?'已核验（用户声明）':'待核验'}}{{s.is_sample?' · 示例数据':''}}</summary><p>原始来源：{{s.origin}}</p><p>授权说明：{{s.authorization}}</p><p>核验说明：{{s.verification_note||'尚未填写'}}</p><p>关联记录：{{records.filter(r=>r.source_id===s.id).length}}（当前页；更早记录请翻页）</p><ul><li v-for="row in records.filter(r=>r.source_id===s.id)" :key="row.id"><button class="text-button" type="button" @click="detail(row)">{{row.code}} · {{row.photo_name||'位置 / 资料记录'}}</button></li></ul></details></section>
  <section class="c-card"><h3>采集记录 · {{total}}条</h3><p v-if="!records.length">暂无记录；保存后可刷新查看。服务错误时请先检查上方提示，不会自动生成示例记录。</p><div class="table-scroll" v-else tabindex="0" aria-label="采集记录表，窄屏可横向滚动"><table><thead><tr><th>编号 / 类型</th><th>采集时间</th><th>位置（GCJ-02）</th><th>来源 / 数据性质</th><th>说明 / 照片</th></tr></thead><tbody><tr v-for="row in records" :key="row.id"><td><button class="text-button" @click="detail(row)">{{row.code}}</button><br/>{{row.kind==='photo'?'照片':row.kind==='location'?'位置':'资料'}}</td><td>{{new Date(row.captured_at).toLocaleString()}}</td><td>{{row.longitude??'未提供'}}, {{row.latitude??'未提供'}}</td><td>{{sourceName(row.source_id)}}<br/>{{row.nature==='sample'?'示例数据':row.nature==='field_declared'?'现场采集（用户声明）':'用户资料（未核验）'}}</td><td>{{row.note||'—'}}<br/>{{row.photo_name||'无照片'}}</td></tr></tbody></table></div><div class="pager"><button :disabled="busy||offset===0" @click="page(-20)">上一页</button><span>{{total?offset+1:0}}—{{Math.min(offset+20,total)}} / {{total}}</span><button :disabled="busy||offset+20>=total" @click="page(20)">下一页</button></div></section>
  <section v-if="selected" class="c-card" aria-live="polite"><h3>记录详情：{{selected.code}}</h3><p>{{selected.note||'未填写说明'}}</p><p>照片名称：{{selected.photo_name||'无照片'}} · SHA256：{{selected.photo_sha256||'无'}}</p><img v-if="selectedPhoto" :src="selectedPhoto" class="photo saved-photo" alt="已保存照片" /><p v-else-if="selected.photo_url">正在读取照片，请检查失败提示。</p><button @click="closeDetail">关闭详情</button></section>
</div>
</template>
<style scoped>
.collection-page{display:grid;gap:20px;color:var(--c-text);max-width:1600px;margin:auto}.eyebrow,.hint{color:var(--c-text-3);font-size:12px;line-height:1.8}h2{font-size:28px;margin:4px 0 12px}h3{margin:0 0 16px;font-size:17px}header>p{line-height:1.8}.c-card{padding:22px;min-width:0}.collection-columns{display:grid;grid-template-columns:1fr 1fr;gap:20px}.right-column{display:grid;gap:20px;align-content:start}form{display:grid;gap:14px}label{display:grid;gap:7px;font-size:13px}input,select,textarea{background:var(--c-bg-2,#101c17);color:var(--c-text);border:1px solid var(--c-border,#33483e);border-radius:7px;padding:10px;min-width:0;width:100%;box-sizing:border-box}textarea{resize:vertical}.field-row{display:grid;grid-template-columns:1fr 1fr;gap:14px}button{border:1px solid #547665;background:#182c23;color:#d4e9dc;border-radius:7px;padding:9px 15px;cursor:pointer}button:disabled{opacity:.5;cursor:not-allowed}.primary{background:#176e4b;color:white}.refresh{justify-self:start}.photo{max-width:100%;max-height:240px;object-fit:contain;border-radius:8px}.saved-photo{max-height:480px}.checkbox{display:flex;align-items:center}.checkbox input{width:auto}.review-form{grid-template-columns:1fr 1fr 2fr auto;align-items:end}.table-scroll{overflow:auto}table{border-collapse:collapse;width:100%;min-width:720px;font-size:12px}td,th{padding:12px;text-align:left;border-bottom:1px solid var(--c-border);vertical-align:top;overflow-wrap:anywhere}.text-button{padding:0;background:none;border:0;color:#a6dec0;text-decoration:underline}.pager{display:flex;gap:16px;align-items:center;justify-content:flex-end;margin-top:18px}.collection-error{padding:14px;border:1px solid #aa6a4d;color:#efc3aa}.collection-success{color:#a3dfbb}details{padding:10px;border-top:1px solid var(--c-border)}p{overflow-wrap:anywhere}button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:2px solid #88d5ae;outline-offset:3px}@media(max-width:900px){.collection-columns,.review-form{grid-template-columns:1fr}.c-card{padding:16px}}@media(max-width:450px){.field-row{grid-template-columns:1fr}.pager{gap:8px;font-size:12px}h2{font-size:23px}}
</style>
